/**
 * @file        build-bravojs-bundle.js
 * @description Flattens wasm/fftw-wasm.js + wasm/fftw-module.js into one
 *              file wrapped in bravojs's module format (module.declare),
 *              the format DCP's package publisher expects -- see
 *              docs/patching-wasm-libraries-for-dcp.pdf in the Edequity
 *              repo (the same pattern used for duckdbwasm and
 *              sofia2wasm). Local (unpublished) job.requires() tolerates
 *              plain CommonJS because it goes through a real webpack
 *              build at deploy time; publish does not, so this file is
 *              pre-wrapped instead.
 *
 * @usage       node build-bravojs-bundle.js
 *              (run after wasm/build.sh; writes package/fftw-wasm.js)
 */
'use strict';

const fs = require('fs');
const path = require('path');

const WASM_DIR = path.join(__dirname, '..');

const moduleSrc = fs.readFileSync(path.join(WASM_DIR, 'fftw-module.js'), 'utf8');
let wrapperSrc = fs.readFileSync(path.join(WASM_DIR, 'fftw-wasm.js'), 'utf8');

// fftw-wasm.js normally does `const createFftwModule = require('./fftw-module');`
// In the bundle, createFftwModule is supplied as a closure parameter instead --
// drop that one line (and only that line; leave everything else, including the
// docblock, untouched for provenance).
const requireLine = "const createFftwModule = require('./fftw-module');\n\n";
if (!wrapperSrc.includes(requireLine)) {
  throw new Error("expected to find require('./fftw-module') line in fftw-wasm.js");
}
wrapperSrc = wrapperSrc.replace(requireLine, '');

const bundle = `/**
 * @file        fftw-wasm.js (published bundle)
 * @description Published-package form of wasm/fftw-wasm.js + wasm/fftw-module.js,
 *              flattened into one file and wrapped in bravojs's module format
 *              (module.declare), per the DCP package publishing convention --
 *              see docs/patching-wasm-libraries-for-dcp.pdf in the Edequity
 *              repo (the same pattern used for duckdbwasm and sofia2wasm).
 *              Generated by build-bravojs-bundle.js; do not hand-edit --
 *              edit wasm/fftw-wasm.js or rerun wasm/build.sh + this script
 *              instead.
 *
 *              Local (unpublished) job.requires() tolerates plain CommonJS
 *              because it goes through a real webpack build at deploy time;
 *              publish does not, so this file is pre-wrapped instead.
 *
 * @usage       job.requires(['fftw3wasm-v3/fftw-wasm.js']);
 *              // inside the work function:
 *              const fftw = require('fftw-wasm.js');  // bare filename, no ./
 *              const { re, im } = await fftw.dft1d(reArray, imArray);
 *              const { re, im } = await fftw.r2c1d(realArray);
 */
module.declare([], function (require, exports, module) {
  // ---- fftw-module.js (Emscripten build of FFTW3 + fdlibm), verbatim ----
  var createFftwModule = (function () {
    var module = { exports: {} };
    var exports = module.exports;
${moduleSrc}
    return module.exports;
  })();

  // ---- fftw-wasm.js, with require('./fftw-module') replaced by the ----
  // ---- createFftwModule captured above ----
  var bundleExports = (function (createFftwModule) {
    var module = { exports: {} };
    var exports = module.exports;
${wrapperSrc}
    return module.exports;
  })(createFftwModule);

  for (var k in bundleExports) {
    if (Object.prototype.hasOwnProperty.call(bundleExports, k)) exports[k] = bundleExports[k];
  }
});
`;

const outPath = path.join(__dirname, 'fftw-wasm.js');
fs.writeFileSync(outPath, bundle);
console.log(`wrote ${outPath} (${bundle.length} bytes)`);
